<template><div class="la">
<header><div><h2>Duyệt nghỉ phép</h2><p>Xem xét và xử lý yêu cầu nghỉ của nhân viên</p></div><v-btn prepend-icon="mdi-refresh" variant="outlined" :loading="loading" @click="load">Làm mới</v-btn></header>
<section class="la-stats"><article v-for="s in summaries" :key="s.key"><i :class="s.key"><v-icon :icon="s.icon"/></i><div><span>{{s.label}}</span><b>{{s.value}}</b></div></article></section>
<section class="la-panel"><div class="la-tools"><div><v-select v-model="statusFilter" :items="statusItems" item-title="label" item-value="value" label="Trạng thái" hide-details @update:model-value="load"/><v-text-field v-model="month" type="month" label="Tháng" clearable hide-details @update:model-value="load"/></div><strong>{{leaves.length}} đơn</strong></div>
<div v-if="error" class="la-error"><v-icon icon="mdi-cloud-alert-outline"/><span>{{error}}</span><v-btn variant="tonal" @click="load">Thử lại</v-btn></div>
<div v-if="loading&&!leaves.length" class="la-loading"><i v-for="i in 4" :key="i"/></div>
<div v-else-if="leaves.length" class="la-list"><article v-for="item in leaves" :key="item.id" class="la-request">
<div class="la-person"><i>{{initials(item.user?.fullName||item.user?.email)}}</i><div><b>{{item.user?.fullName||item.user?.email||'—'}}</b><span>{{item.user?.email&&item.user?.fullName?item.user.email:'Nhân viên'}}</span></div></div>
<div class="la-kind"><b>{{LEAVE_TYPE_LABEL[item.type]||item.type}}</b><span>{{LEAVE_SESSION_LABEL[item.session]||item.session}}</span></div>
<div class="la-dates"><v-icon icon="mdi-calendar-range-outline" size="18"/><div><b>{{fmt(item.startDate)}}<template v-if="item.endDate!==item.startDate"> – {{fmt(item.endDate)}}</template></b><span>Thời gian nghỉ</span></div></div>
<div class="la-reason"><span>Lý do</span><p>{{item.reason}}</p></div>
<span class="la-badge" :class="item.status"><v-icon :icon="statusIcon(item.status)" size="15"/>{{LEAVE_STATUS[item.status]?.label||item.status}}</span>
<div class="la-actions" v-if="item.status==='pending'&&canReview"><v-btn color="success" variant="tonal" prepend-icon="mdi-check" @click="open(item,'approved')">Duyệt</v-btn><v-btn color="error" variant="tonal" prepend-icon="mdi-close" @click="open(item,'rejected')">Từ chối</v-btn></div><div v-else class="la-reviewed">{{item.reviewedBy?.fullName||'Đã xử lý'}}</div>
</article></div>
<div v-else class="la-empty"><v-icon icon="mdi-calendar-check-outline" size="38"/><h3>Không có đơn nghỉ phù hợp</h3><p>Đổi trạng thái hoặc tháng để xem yêu cầu khác.</p><v-btn color="primary" variant="tonal" @click="reset">Xóa bộ lọc</v-btn></div></section>
<v-dialog v-model="dialog" max-width="520" persistent><v-card class="la-dialog"><div class="la-dh" :class="action"><v-icon :icon="action==='approved'?'mdi-check-circle-outline':'mdi-close-circle-outline'" size="30"/><div><h3>{{action==='approved'?'Duyệt đơn nghỉ':'Từ chối đơn nghỉ'}}</h3><p>Xác nhận quyết định và gửi phản hồi cho nhân viên</p></div></div><v-card-text><div class="la-summary"><b>{{selected?.user?.fullName||selected?.user?.email}}</b><span>{{LEAVE_TYPE_LABEL[selected?.type]}} · {{fmt(selected?.startDate)}}</span><p>{{selected?.reason}}</p></div><v-textarea v-model="note" label="Ghi chú cho nhân viên (không bắt buộc)" rows="3" maxlength="300" counter/></v-card-text><v-card-actions><v-spacer/><v-btn variant="outlined" @click="dialog=false">Huỷ</v-btn><v-btn :color="action==='approved'?'success':'error'" :loading="reviewing" @click="confirm">{{action==='approved'?'Xác nhận duyệt':'Xác nhận từ chối'}}</v-btn></v-card-actions></v-card></v-dialog>
</div></template>
<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{api}from'@/api';import{useToast}from'@/composables/use-toast';import{useAuthStore}from'@/stores/auth';import{LEAVE_TYPE_LABEL,LEAVE_SESSION_LABEL,LEAVE_STATUS}from'@/constants/hr';const toast=useToast(),auth=useAuthStore(),canReview=auth.canAccess('leave','edit');const statusItems=[{value:'all',label:'Tất cả trạng thái'},{value:'pending',label:'Chờ duyệt'},{value:'approved',label:'Đã duyệt'},{value:'rejected',label:'Từ chối'}],statusFilter=ref('pending'),month=ref<string|null>(null),leaves=ref<any[]>([]),loading=ref(false),error=ref(''),dialog=ref(false),selected=ref<any>(),action=ref<'approved'|'rejected'>('approved'),note=ref(''),reviewing=ref(false);const counts=computed(()=>leaves.value.reduce((a:any,x:any)=>(a[x.status]=(a[x.status]||0)+1,a),{}));const summaries=computed(()=>[{key:'pending',label:'Chờ duyệt',icon:'mdi-clock-outline',value:counts.value.pending||0},{key:'approved',label:'Đã duyệt',icon:'mdi-check-circle-outline',value:counts.value.approved||0},{key:'rejected',label:'Đã từ chối',icon:'mdi-close-circle-outline',value:counts.value.rejected||0},{key:'total',label:'Tổng yêu cầu',icon:'mdi-file-document-multiple-outline',value:leaves.value.length}]);function fmt(d?:string){if(!d)return'';const[y,m,x]=d.split('-');return`${x}/${m}/${y}`}function initials(n?:string){return n?n.trim().split(/\s+/).slice(-2).map(x=>x[0]).join('').toUpperCase():'?'}function statusIcon(s:string){return s==='approved'?'mdi-check-circle-outline':s==='rejected'?'mdi-close-circle-outline':'mdi-clock-outline'}async function load(){loading.value=true;error.value='';try{const p:Record<string,string>={};if(statusFilter.value!=='all')p.status=statusFilter.value;if(month.value)p.month=month.value;const r=await api.get('/leave',{params:p});leaves.value=r.data.records??r.data.leaves??[]}catch(e:any){leaves.value=[];error.value=e?.response?.data?.hint||e?.response?.data?.error||'Không tải được danh sách'}finally{loading.value=false}}function reset(){statusFilter.value='all';month.value=null;load()}function open(i:any,a:'approved'|'rejected'){selected.value=i;action.value=a;note.value='';dialog.value=true}async function confirm(){reviewing.value=true;try{await api.patch(`/leave/${selected.value.id}/review`,{status:action.value,reviewNote:note.value.trim()||undefined});toast.success(action.value==='approved'?'Đã duyệt đơn nghỉ':'Đã từ chối đơn nghỉ');dialog.value=false;await load()}catch(e:any){toast.error(e?.response?.data?.hint||'Thao tác thất bại')}finally{reviewing.value=false}}onMounted(load)</script>
<style scoped>.la{max-width:1680px;margin:auto;color:var(--smax-text)}header{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}h2{font-size:23px;margin:0}header p{font-size:14px;color:#667085;margin:4px 0}.la-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:14px}.la-stats article{display:flex;align-items:center;gap:13px;padding:16px;border:1px solid #e5e8ed;border-radius:14px;background:#fff}.la-stats i{width:44px;height:44px;display:grid;place-items:center;border-radius:11px}.la-stats .pending{background:#fff4df;color:#9a610b}.la-stats .approved{background:#eaf9f2;color:#147a55}.la-stats .rejected{background:#fff0f1;color:#c4373e}.la-stats .total{background:var(--smax-primary-soft);color:var(--smax-primary)}.la-stats article div{display:flex;flex-direction:column}.la-stats span{font-size:13px;color:#667085}.la-stats b{font-size:24px}.la-panel{border:1px solid #e5e8ed;border-radius:15px;background:#fff;overflow:hidden}.la-tools{display:flex;justify-content:space-between;align-items:center;padding:14px 16px;background:#fafbfc;border-bottom:1px solid #e8ebf0}.la-tools>div{display:flex;gap:10px;width:430px}.la-tools>div>*{flex:1}.la-tools>strong{font-size:14px;color:var(--smax-primary)}.la-list{padding:12px;background:#f7f8fc}.la-request{display:grid;grid-template-columns:1.15fr .75fr .9fr 1.35fr auto auto;align-items:center;gap:15px;padding:15px;margin-bottom:9px;border:1px solid #e2e6ec;border-radius:13px;background:#fff}.la-person,.la-dates{display:flex;align-items:center;gap:10px}.la-person>i{width:42px;height:42px;display:grid;place-items:center;border-radius:11px;background:var(--smax-primary-soft);color:var(--smax-primary);font-style:normal;font-weight:800}.la-person div,.la-kind,.la-dates div{display:flex;flex-direction:column;gap:3px;min-width:0}.la-person b,.la-kind b,.la-dates b{font-size:14px}.la-person span,.la-kind span,.la-dates span,.la-reason>span{font-size:12px;color:#7d8491}.la-reason p{margin:3px 0;font-size:14px;line-height:1.4}.la-badge{display:flex;align-items:center;gap:5px;padding:7px 10px;border-radius:99px;font-size:12.5px;font-weight:700;white-space:nowrap}.la-badge.pending{background:#fff4df;color:#9a610b}.la-badge.approved{background:#eaf9f2;color:#147a55}.la-badge.rejected{background:#fff0f1;color:#c4373e}.la-actions{display:flex;gap:7px}.la-actions .v-btn{font-size:13px;font-weight:700}.la-reviewed{font-size:12px;color:#717784}.la-empty{min-height:330px;display:flex;flex-direction:column;align-items:center;justify-content:center}.la-empty h3{font-size:18px;margin:12px 0 4px}.la-empty p{font-size:14px;color:#737b89}.la-error{display:flex;align-items:center;gap:10px;margin:14px;padding:12px;background:#fff1f2;color:#b4232b;border-radius:10px}.la-error span{flex:1}.la-loading{padding:15px}.la-loading i{display:block;height:72px;background:#f1f3f6;margin:8px;border-radius:10px}.la-dialog{border-radius:16px!important}.la-dh{display:flex;align-items:center;gap:12px;padding:20px}.la-dh.approved{background:#f0fbf6;color:#147a55}.la-dh.rejected{background:#fff4f4;color:#c4373e}.la-dh h3{font-size:20px;margin:0}.la-dh p{font-size:13px;color:#667085;margin:3px 0}.la-summary{display:flex;flex-direction:column;gap:4px;padding:14px;margin-bottom:15px;background:#f7f8fa;border-radius:11px}.la-summary b{font-size:15px}.la-summary span{font-size:13px;color:#667085}.la-summary p{font-size:14px;margin:7px 0}.la-dialog .v-card-actions{padding:12px 20px 18px}.la-dialog .v-btn{min-height:42px;font-size:14px;font-weight:700}@media(max-width:1200px){.la-request{grid-template-columns:1fr 1fr 1fr}.la-reason{grid-column:1/3}.la-actions,.la-reviewed{justify-self:end}}@media(max-width:800px){.la-stats{grid-template-columns:1fr 1fr}.la-tools{align-items:stretch;flex-direction:column;gap:10px}.la-tools>div{width:100%}.la-request{grid-template-columns:1fr}.la-reason{grid-column:auto}.la-actions,.la-reviewed{justify-self:stretch}.la-actions>*{flex:1}}@media(max-width:550px){.la-stats{gap:8px}.la-stats article{padding:11px}.la-stats i{width:36px;height:36px}.la-tools>div{flex-direction:column}.la-request{padding:13px}.la-actions{display:grid;grid-template-columns:1fr 1fr}header .v-btn{min-width:42px}}
</style>
